import bpy,json,pathlib
out=pathlib.Path('/Users/yiouchen/.codex/worktrees/warm-soft-catalog/game-prototype/prototypes/sushi-loop/assets/refinement/objects/chef-rowan/reviews')
def vec(v): return [float(x) for x in v]
data={'scenes':[{'name':s.name,'camera':s.camera.name if s.camera else None,'resolution':[s.render.resolution_x,s.render.resolution_y,s.render.resolution_percentage],'fps':s.render.fps,'collections':[c.name for c in s.collection.children]} for s in bpy.data.scenes], 'collections':[{'name':c.name,'hide_viewport':c.hide_viewport,'hide_render':c.hide_render,'objects':len(c.all_objects)} for c in bpy.data.collections if 'rowan' in c.name.lower()], 'objects':[{'name':o.name,'type':o.type,'parent':o.parent.name if o.parent else None,'location':vec(o.location),'rotation':vec(o.rotation_euler),'hide_viewport':o.hide_viewport,'hide_render':o.hide_render,'props':{k:str(v) for k,v in o.items()}} for o in bpy.data.objects if 'rowan' in o.name.lower()], 'cameras':[{'name':o.name,'matrix':[list(r) for r in o.matrix_world],'data':{'type':o.data.type,'ortho_scale':o.data.ortho_scale,'shift_x':o.data.shift_x,'shift_y':o.data.shift_y}} for o in bpy.data.objects if o.type=='CAMERA']}
(out/'source_inventory.json').write_text(json.dumps(data,indent=2))
print('ROWAN_INVENTORY',json.dumps({'scenes':data['scenes'],'collections':data['collections'],'camera_names':[o['name'] for o in data['cameras']],'rowan_objects':len(data['objects'])}))
